window.QBANK["m4w2"] = [
  {"level": 1, "q": "File settings nào của Claude Code có mức ưu tiên cao nhất và người dùng không thể ghi đè?", "options": ["Managed settings do IT/tổ chức triển khai", "~/.claude/settings.json của người dùng", ".claude/settings.json commit trong repo", "CLAUDE.md ở thư mục gốc monorepo"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Managed settings nằm ở tầng cao nhất của thứ tự ưu tiên và được thiết kế để áp chính sách tổ chức mà người dùng không ghi đè được.<br><strong>Vì sao các lựa chọn khác sai:</strong> File user và file project đều nằm dưới managed trong thứ tự ưu tiên; CLAUDE.md chỉ là chỉ dẫn cho model, không phải cơ chế cấu hình quyền."},
  {"level": 1, "q": "Thứ tự ưu tiên đúng của các nguồn settings trong Claude Code (từ cao xuống thấp) là gì?", "options": ["~/.claude/settings.json &gt; .claude/settings.json &gt; .claude/settings.local.json &gt; managed", "managed &gt; --settings &gt; .claude/settings.local.json &gt; .claude/settings.json &gt; ~/.claude/settings.json", ".claude/settings.json &gt; .claude/settings.local.json &gt; managed &gt; --settings", "--settings &gt; managed &gt; ~/.claude/settings.json &gt; .claude/settings.local.json"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Chính sách tổ chức đứng đầu, rồi tới tham số dòng lệnh cho lần chạy, rồi thiết lập riêng của bạn trong project, rồi file team, cuối cùng là thói quen cá nhân ở cấp user.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các thứ tự còn lại đảo vị trí managed hoặc đặt file user/project lên trên file local, trái với quy tắc “cụ thể hơn thì ưu tiên hơn” và “tổ chức luôn thắng”."},
  {"level": 1, "q": "File <code>.claude/settings.local.json</code> dùng để làm gì?", "options": ["Thiết lập dùng chung cho cả team, bắt buộc commit", "Cấu hình danh sách MCP server của project", "Thiết lập cấp project chỉ dành cho riêng bạn, không commit lên git", "Lưu chỉ dẫn coding style cho model"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> settings.local.json là tầng “ghi chú riêng”: áp dụng trong project đó nhưng chỉ trên máy bạn và thường nằm trong .gitignore.<br><strong>Vì sao các lựa chọn khác sai:</strong> File dùng chung cho team là .claude/settings.json; MCP server khai báo trong .mcp.json; chỉ dẫn coding style thuộc về CLAUDE.md."},
  {"level": 1, "q": "Ba loại rule trong khối <code>permissions</code> của settings là gì?", "options": ["read, write, execute", "include, exclude, override", "public, private, protected", "allow, ask, deny"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Claude Code phân quyền theo ba danh sách: allow (chạy không hỏi), ask (luôn hỏi) và deny (chặn hẳn).<br><strong>Vì sao các lựa chọn khác sai:</strong> read/write/execute là quyền hệ điều hành; include/exclude/override và public/private/protected không phải khoá hợp lệ trong permissions."},
  {"level": 1, "q": "Cho settings:<pre><code>{\n  \"permissions\": {\n    \"allow\": [\"Bash(pnpm --filter db exec prisma:*)\"],\n    \"ask\":   [\"Bash(pnpm --filter db exec prisma migrate:*)\"]\n  }\n}</code></pre>Claude chạy <code>pnpm --filter db exec prisma migrate dev</code> – lệnh khớp cả allow lẫn ask. Claude Code xử lý thế nào?", "options": ["Chạy ngay vì allow được xét trước", "Hỏi người dùng trước khi chạy, vì ask chặt hơn allow", "Chặn hẳn như deny", "Tuỳ rule nào đứng trước trong file JSON"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Quy tắc gộp là rule chặt nhất thắng: deny > ask > allow, nên khi vừa ask vừa allow thì hỏi người dùng.<br><strong>Vì sao các lựa chọn khác sai:</strong> allow không được ưu tiên hơn ask; ask không biến thành deny; thứ tự dòng trong file không ảnh hưởng tới kết quả."},
  {"level": 1, "q": "Rule nào cho phép chạy mọi lệnh bắt đầu bằng <code>pnpm test</code> (vd. <code>pnpm test --filter api</code>) mà không hỏi?", "options": ["\"Bash(pnpm test)\" trong danh sách deny", "\"Run(pnpm test)\" trong danh sách allow", "\"Bash(pnpm test:*)\" trong danh sách allow", "\"pnpm test\" trong khối env"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Cú pháp Bash(lệnh:*) là so khớp tiền tố cho lệnh Bash, đặt trong allow để chạy không cần hỏi.<br><strong>Vì sao các lựa chọn khác sai:</strong> Đặt vào deny sẽ chặn chứ không cho phép; không có tool tên Run; khối env chỉ khai báo biến môi trường, không cấp quyền."},
  {"level": 1, "q": "Tên rule đúng để chỉ tool <code>query</code> của MCP server tên <code>postgres</code> là gì?", "options": ["postgres.query", "MCP(postgres/query)", "mcp:postgres:query", "mcp__postgres__query"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Tool MCP trong Claude Code được đặt tên theo quy ước mcp__tên-server__tên-tool và dùng nguyên tên đó trong rule.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các dạng dấu chấm, dấu gạch chéo hay dấu hai chấm không khớp quy ước nên rule sẽ không có tác dụng."},
  {"level": 1, "q": "Permission mode nào cho Claude chỉ đọc code và lên kế hoạch, không sửa file?", "options": ["plan", "acceptEdits", "bypassPermissions", "default kèm allow Edit"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Plan mode dùng để khám phá và đề xuất; Claude không thực hiện thay đổi cho tới khi bạn duyệt kế hoạch.<br><strong>Vì sao các lựa chọn khác sai:</strong> acceptEdits tự chấp nhận sửa file; bypassPermissions bỏ qua gần như mọi kiểm tra; default kèm allow Edit vẫn cho sửa file."},
  {"level": 1, "q": "Permission mode <code>acceptEdits</code> có tác dụng gì?", "options": ["Chấp nhận mọi lệnh Bash kể cả git push", "Chặn toàn bộ thao tác sửa file", "Tự động chấp nhận các thao tác sửa file, các hành động khác vẫn theo rule như bình thường", "Tắt toàn bộ rule deny"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> acceptEdits giảm số lần xác nhận khi Claude sửa file, còn lệnh ra ngoài như git push vẫn bị hỏi nếu có rule ask.<br><strong>Vì sao các lựa chọn khác sai:</strong> Mode này không cấp quyền cho mọi lệnh Bash; nó ngược với việc chặn sửa file; rule deny vẫn luôn có hiệu lực."},
  {"level": 1, "q": "Lệnh nào trong phiên Claude Code để xem và chỉnh các rule permission đang áp dụng?", "options": ["/config-rules", "/allow", "/security", "/permissions"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> /permissions hiển thị các rule allow/ask/deny đang được nạp từ mọi tầng settings và cho phép chỉnh.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các lệnh còn lại không phải lệnh tích hợp để quản lý quyền trong Claude Code."},
  {"level": 1, "q": "Rule nào chặn Claude dùng tool Read để đọc file <code>.env</code> ở gốc repo?", "options": ["\"Read(./.env)\" trong danh sách deny", "\"Read(./.env)\" trong danh sách allow", "\".env\" trong CLAUDE.md", "\"Bash(.env)\" trong danh sách ask"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Rule Read(đường-dẫn) trong deny chặn tool Read truy cập file tương ứng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Đặt trong allow là cho phép; ghi vào CLAUDE.md chỉ là lời dặn không cưỡng chế; Bash(.env) không mô tả thao tác đọc file bằng tool Read."},
  {"level": 1, "q": "File <code>.claude/settings.json</code> trong monorepo thường được dùng thế nào?", "options": ["Không bao giờ commit vì chứa secret", "Commit lên git để cả team dùng chung một chính sách", "Chỉ có hiệu lực trên CI", "Chỉ đọc khi chạy với cờ --settings"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Đây là tầng project dùng chung, thường commit để mọi người clone repo đều có cùng rule.<br><strong>Vì sao các lựa chọn khác sai:</strong> File này không nên chứa secret nên commit được; nó có hiệu lực cả ở máy dev lẫn CI; không cần cờ --settings để được nạp."},
  {"level": 1, "q": "File settings cấp user áp dụng cho mọi project nằm ở đâu?", "options": ["./.claude/settings.json", "/etc/claude/CLAUDE.md", "./settings.user.json", "~/.claude/settings.json"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Settings cấp user đặt trong thư mục home ~/.claude/settings.json và áp dụng cho mọi project trên máy.<br><strong>Vì sao các lựa chọn khác sai:</strong> ./.claude/settings.json là cấp project; CLAUDE.md không phải file settings; settings.user.json không phải tên file mà Claude Code đọc."},
  {"level": 1, "q": "Khối nào trong settings.json dùng để khai báo biến môi trường cho phiên Claude Code?", "options": ["\"env\"", "\"variables\"", "\"permissions.env\"", "\"dotenv\""], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Khoá env trong settings nhận một object tên biến → giá trị, được áp cho phiên làm việc.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các khoá variables, permissions.env hay dotenv không phải khoá chuẩn cho biến môi trường trong settings."},
  {"level": 1, "q": "Theo bảng thiết kế chính sách của bài, lệnh <code>git diff</code> nên được xếp vào nhóm nào?", "options": ["deny – có thể lộ secret", "allow – lệnh chỉ đọc, không tác dụng phụ", "ask – tác động ra ngoài", "Không cần rule vì Claude không dùng git"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> git diff chỉ đọc trạng thái repo, không thay đổi gì nên thuộc nhóm allow để giảm số lần bị hỏi.<br><strong>Vì sao các lựa chọn khác sai:</strong> git diff không phải lệnh phá huỷ hay lệnh ra ngoài; Claude dùng git rất thường xuyên nên rule vẫn cần thiết."},
  {"level": 1, "q": "Lệnh <code>git push</code> nên được đặt ở danh sách nào theo nguyên tắc của bài?", "options": ["allow – vì là thao tác thường ngày", "deny – vì không bao giờ được push", "ask – vì tác động ra bên ngoài máy", "env – để cấu hình remote"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Hành động tác động ra ngoài (push, tạo issue, gửi tin) nên luôn hỏi để con người xác nhận.<br><strong>Vì sao các lựa chọn khác sai:</strong> allow bỏ qua bước xác nhận quan trọng; deny hoàn toàn thì chặn cả quy trình hợp lệ; env không liên quan tới quyền."},
  {"level": 1, "q": "Lệnh <code>rm -rf</code> nên được xử lý thế nào trong chính sách permission?", "options": ["Đặt \"Bash(rm -rf:*)\" vào deny", "Đặt vào allow để dọn dẹp nhanh", "Đặt vào ask để hỏi mỗi lần", "Không cần rule vì Claude không bao giờ chạy lệnh này"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Lệnh phá huỷ khó đảo ngược thuộc nhóm deny để chặn hẳn.<br><strong>Vì sao các lựa chọn khác sai:</strong> allow quá rủi ro; ask vẫn có thể bị bấm nhầm “cho phép”; không có gì đảm bảo model không bao giờ chạy lệnh này."},
  {"level": 1, "q": "Hook nào chạy TRƯỚC bước kiểm tra permission rule khi Claude chuẩn bị gọi một tool?", "options": ["PostToolUse", "PreToolUse", "Stop", "SessionEnd"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> PreToolUse chạy trước kiểm tra quyền thông thường, có thể chặn, sửa input hoặc tự quyết định quyền.<br><strong>Vì sao các lựa chọn khác sai:</strong> PostToolUse chạy sau khi tool đã chạy; Stop chạy khi Claude trả lời xong; SessionEnd chạy khi phiên kết thúc."},
  {"level": 1, "q": "Cờ dòng lệnh nào cho phép truyền một file settings bổ sung cho riêng lần chạy Claude Code đó?", "options": ["--config-file", "--profile", "--settings", "--policy"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Cờ --settings nạp thêm settings từ một file (hoặc chuỗi JSON) cho lần chạy, xếp ngay dưới managed trong thứ tự ưu tiên.<br><strong>Vì sao các lựa chọn khác sai:</strong> --config-file, --profile, --policy không phải cờ của Claude Code để nạp settings."},
  {"level": 1, "q": "Khi chạy headless trong CI, cờ nào giới hạn các tool Claude được dùng mà không cần hỏi?", "options": ["--tools-only", "--sandbox-tools", "--safe", "--allowedTools"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> --allowedTools liệt kê các tool/rule (vd. \"Read,Bash(pnpm test:*)\") được phép chạy trong lần gọi claude -p.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các cờ còn lại không phải cờ hợp lệ của Claude Code."},
  {"level": 1, "q": "Cờ nào chặn một số tool cụ thể khi chạy <code>claude -p</code>?", "options": ["--denyTools", "--disallowedTools", "--blockTools", "--no-tools"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> --disallowedTools nhận danh sách tool/rule bị chặn cho lần chạy đó, tương đương rule deny.<br><strong>Vì sao các lựa chọn khác sai:</strong> --denyTools, --blockTools, --no-tools không phải cờ thật của Claude Code."},
  {"level": 1, "q": "Trong settings.json, khoá nào đặt permission mode mặc định cho project?", "options": ["\"mode\": \"...\" ở gốc file", "\"permissions\": { \"level\": \"...\" }", "\"permissions\": { \"defaultMode\": \"...\" }", "\"env\": { \"CLAUDE_MODE\": \"...\" }"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> defaultMode nằm trong khối permissions và nhận giá trị như default, acceptEdits hoặc plan.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các khoá mode, level hay biến CLAUDE_MODE không phải cách chuẩn để đặt permission mode mặc định."},
  {"level": 1, "q": "Vì sao đã có <code>.env</code> trong <code>.gitignore</code> mà vẫn nên deny <code>Read(./.env)</code>?", "options": [".gitignore tự động xoá file .env", "Claude Code bỏ qua mọi file trong .gitignore khi đọc", "Deny Read giúp file .env không bị commit", ".gitignore chỉ ngăn commit, không ngăn Claude đọc file trên đĩa"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> .gitignore và rule deny giải quyết hai việc khác nhau: một cái chặn đưa lên git, một cái chặn Claude đọc nội dung vào hội thoại.<br><strong>Vì sao các lựa chọn khác sai:</strong> .gitignore không xoá file; không có đảm bảo Claude bỏ qua file bị ignore khi dùng Read; deny Read không liên quan tới việc commit."},
  {"level": 1, "q": "Rule permission nằm ở nhiều tầng như sau:<pre><code>// ~/.claude/settings.json\n{ \"permissions\": { \"allow\": [\"Bash(git log:*)\"] } }\n\n// .claude/settings.json\n{ \"permissions\": { \"deny\": [\"Read(./.env)\"] } }\n\n// .claude/settings.local.json\n{ \"permissions\": { \"allow\": [\"Bash(pnpm dev)\"] } }</code></pre>Các danh sách này kết hợp thế nào?", "options": ["Được gộp lại từ mọi tầng, rồi áp quy tắc deny &gt; ask &gt; allow", "Chỉ lấy tầng ưu tiên cao nhất, bỏ các tầng còn lại", "Tầng user luôn thay thế tầng project", "Chỉ lấy file được sửa gần nhất"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Danh sách permission được gộp; một rule deny ở bất kỳ tầng nào vẫn chặn được allow ở tầng khác.<br><strong>Vì sao các lựa chọn khác sai:</strong> Rule không bị thay thế nguyên khối theo tầng; user không thay thế project; thời điểm sửa file không quyết định rule."},
  {"level": 1, "q": "Trong Claude Code, chế độ <code>bypassPermissions</code> (cờ <code>--dangerously-skip-permissions</code>) phù hợp nhất với môi trường nào?", "options": ["Laptop cá nhân có SSH key và quyền push production", "Máy chủ bastion kết nối RDS production", "Container/sandbox cô lập, dùng một lần, không có secret hay quyền truy cập thật", "Máy dev đang mở phiên AWS admin"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Chế độ bỏ qua kiểm tra quyền chỉ chấp nhận được khi môi trường bị cô lập và thiệt hại nếu sai là nhỏ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các môi trường còn lại chứa credential thật; một lệnh sai có thể push code, xoá dữ liệu hoặc lộ secret."},
  {"level": 1, "q": "Rule nào áp dụng cho TẤT CẢ tool của MCP server tên <code>github</code>?", "options": ["\"github\"", "\"mcp__*__github\"", "\"MCP(github)\"", "\"mcp__github\""], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Viết tên server với tiền tố mcp__ (không kèm tên tool) sẽ khớp mọi tool do server đó cung cấp.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tên trần \"github\" không khớp quy ước; mcp__*__github đặt sai vị trí tên server; MCP(github) không phải cú pháp rule."},
  {"level": 1, "q": "Hook <code>PermissionRequest</code> được kích hoạt khi nào?", "options": ["Khi Claude Code chuẩn bị hiện hộp thoại xin quyền cho người dùng", "Mỗi khi phiên bắt đầu", "Sau khi tool chạy xong", "Khi người dùng gõ /permissions"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> PermissionRequest chạy ở điểm cần hỏi quyền (vd. khớp rule ask), cho phép tự duyệt hoặc từ chối theo chính sách.<br><strong>Vì sao các lựa chọn khác sai:</strong> Bắt đầu phiên là SessionStart; sau khi tool chạy là PostToolUse; lệnh /permissions chỉ mở giao diện xem rule."},
  {"level": 1, "q": "Mục đích chính của rule <code>ask</code> là gì?", "options": ["Hỏi model xem có nên chạy không", "Luôn yêu cầu con người xác nhận trước khi hành động chạy", "Ghi log hành động mà không chặn", "Chạy thử ở chế độ dry-run"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> ask đặt con người vào vòng lặp cho các hành động có tác động, ví dụ push hay tạo issue.<br><strong>Vì sao các lựa chọn khác sai:</strong> Model không tự duyệt rule ask; ask không chỉ ghi log; Claude Code không tự chuyển lệnh sang dry-run."},
  {"level": 1, "q": "Khi Claude bị chặn bởi rule deny, điều gì xảy ra với phiên làm việc?", "options": ["Phiên bị kết thúc ngay", "Claude Code tự xoá rule deny", "Lệnh vẫn chạy nhưng không hiện kết quả", "Tool không chạy, Claude nhận thông báo bị chặn và có thể chọn cách khác"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Deny chặn riêng lần gọi tool đó; Claude được báo để điều chỉnh, ví dụ đọc file cấu hình khác thay cho .env.<br><strong>Vì sao các lựa chọn khác sai:</strong> Phiên không bị dừng; rule không tự biến mất; lệnh bị chặn thì không chạy chút nào."},
  {"level": 1, "q": "Loại thông tin nào KHÔNG nên đặt trong <code>.claude/settings.json</code> được commit?", "options": ["API key hay token thật (vd. ANTHROPIC_API_KEY)", "Rule deny đọc file .env", "Rule allow cho pnpm lint", "defaultMode của project"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> File commit được mọi người và cả lịch sử git nhìn thấy nên không được chứa secret.<br><strong>Vì sao các lựa chọn khác sai:</strong> Rule deny, rule allow cho lệnh an toàn và defaultMode là cấu hình chính sách, nên chia sẻ cho team."},
  {"level": 2, "q": "Cho settings của team trong monorepo:<pre><code>{\n  \"permissions\": {\n    \"allow\": [\"Bash(pnpm --filter api test:*)\"],\n    \"deny\":  [\"Bash(pnpm --filter api test:e2e)\"]\n  }\n}</code></pre>Claude chạy <code>pnpm --filter api test:e2e</code>. Kết quả?", "options": ["Chạy không hỏi vì khớp allow trước", "Bị chặn vì khớp rule deny, deny thắng allow", "Hỏi người dùng vì hai rule mâu thuẫn", "Lỗi cấu hình khiến toàn bộ file bị bỏ qua"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Lệnh khớp cả hai rule; theo quy tắc deny > ask > allow, rule deny có hiệu lực.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thứ tự khai báo không quyết định; mâu thuẫn không chuyển thành ask; hai rule chồng nhau là hợp lệ, không làm hỏng file."},
  {"level": 2, "q": "Dev muốn trên máy mình <code>pnpm dev</code> chạy không hỏi, nhưng không muốn ảnh hưởng đồng đội. Cấu hình đúng là?", "options": ["Thêm vào allow trong .claude/settings.json rồi commit", "Ghi “được chạy pnpm dev” vào CLAUDE.md", "Thêm \"Bash(pnpm dev)\" vào allow trong .claude/settings.local.json", "Thêm vào managed settings của công ty"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> settings.local.json là tầng project chỉ áp dụng cho máy bạn, không commit nên không ảnh hưởng team.<br><strong>Vì sao các lựa chọn khác sai:</strong> settings.json commit sẽ áp cho mọi người; CLAUDE.md không cấp quyền; managed settings là chính sách toàn tổ chức, quá rộng cho nhu cầu cá nhân."},
  {"level": 2, "q": "Đoạn settings sau có vấn đề gì?<pre><code>{\n  \"permissions\": {\n    \"allow\": [\"Bash(*)\"],\n    \"deny\": [\"Bash(rm -rf:*)\"]\n  }\n}</code></pre>", "options": ["allow quá rộng: mọi lệnh Bash không nằm trong deny đều chạy không hỏi, kể cả git push hay curl", "Không có vấn đề, deny đã chặn lệnh nguy hiểm", "Cú pháp Bash(*) không hợp lệ nên bị bỏ qua hoàn toàn", "deny không có tác dụng khi allow có wildcard"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Blocklist chỉ chặn được những gì bạn nghĩ tới; các lệnh tác động ra ngoài hoặc phá huỷ theo cách khác vẫn lọt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Một rule deny không đủ bao quát; không nên dựa vào việc cú pháp bị bỏ qua; deny vẫn thắng allow kể cả khi allow là wildcard."},
  {"level": 2, "q": "Settings hiện tại:<pre><code>{\n  \"permissions\": {\n    \"allow\": [\"Bash(cat:*)\", \"Bash(grep:*)\"],\n    \"deny\":  [\"Read(./.env)\"]\n  }\n}</code></pre>Claude vẫn đọc được secret trong <code>.env</code> qua cách nào?", "options": ["Dùng tool Read với đường dẫn ./.env", "Chạy lệnh Bash như cat .env hoặc grep trong file đó", "Không có cách nào", "Đọc qua hook PostToolUse"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Rule Read chỉ áp cho tool Read; Bash là tool khác nên cần deny Bash(cat .env*) hoặc hook PreToolUse lọc lệnh.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tool Read với đúng đường dẫn đó đã bị chặn; nói “không có cách nào” bỏ qua đường Bash; hook do bạn viết, không phải kênh để Claude đọc file."},
  {"level": 2, "q": "Workflow CI chạy review PR như sau:<pre><code>- run: |\n    npx @anthropic-ai/claude-code -p \"Review diff của PR này\" \\\n      --allowedTools \"Read,Grep,Glob,Bash(git diff:*)\" \\\n      --output-format json &gt; review.json</code></pre>Claude muốn chạy <code>pnpm install</code>. Điều gì xảy ra?", "options": ["Chạy bình thường vì CI có quyền root", "Workflow treo chờ người bấm cho phép", "Không chạy được vì lệnh không nằm trong --allowedTools và không có người để hỏi", "Claude Code tự thêm lệnh vào allow"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Ở chế độ headless, hành động cần xin quyền mà không được allow sẽ bị từ chối; Claude nhận thông báo và tiếp tục với tool được phép.<br><strong>Vì sao các lựa chọn khác sai:</strong> Quyền root của runner không liên quan tới permission của Claude Code; phiên -p không treo chờ hộp thoại; Claude Code không tự nới rule."},
  {"level": 2, "q": "Cần một rule cho phép Claude gọi mọi tool đọc của MCP server <code>linear</code> nhưng luôn hỏi trước khi <code>create_issue</code>. Cấu hình nào đúng?", "options": ["allow [\"mcp__linear__create_issue\"] và ask [\"mcp__linear\"]", "deny [\"mcp__linear\"] và allow [\"mcp__linear__create_issue\"]", "ask [\"linear.*\"]", "allow [\"mcp__linear\"] và ask [\"mcp__linear__create_issue\"]"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> allow cho cả server, còn ask cho tool cụ thể; vì ask chặt hơn allow nên create_issue vẫn luôn bị hỏi.<br><strong>Vì sao các lựa chọn khác sai:</strong> Đảo ngược làm mọi tool bị hỏi còn create_issue được thả; deny cả server sẽ chặn luôn create_issue; linear.* không phải cú pháp tên tool MCP."},
  {"level": 2, "q": "Repo mới clone có settings:<pre><code>{ \"permissions\": { \"ask\": [\"Bash(git push:*)\"] } }</code></pre>Bạn thấy <code>pnpm lint</code>, <code>pnpm typecheck</code> bị hỏi quyền liên tục. Bước hợp lý đầu tiên?", "options": ["Chuyển sang bypassPermissions cho nhanh", "Thêm các lệnh chỉ kiểm tra này vào allow, còn lệnh ghi ra ngoài vẫn để ask", "Xoá toàn bộ rule deny", "Tắt hook PreToolUse"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Lệnh lint/typecheck không có tác dụng phụ nên allow là an toàn, giảm “mệt mỏi xác nhận” mà vẫn giữ kiểm soát.<br><strong>Vì sao các lựa chọn khác sai:</strong> bypassPermissions bỏ hết lớp bảo vệ; xoá deny làm tăng rủi ro; hook không phải nguyên nhân các câu hỏi quyền này."},
  {"level": 2, "q": "Đoạn <code>.claude/settings.json</code> sau bị Claude Code bỏ qua. Nguyên nhân khả dĩ nhất?<pre><code>{\n  \"permissions\": {\n    \"allow\": [\n      \"Bash(pnpm test:*)\",\n      \"Bash(git status)\",\n    ]\n  }\n}</code></pre>", "options": ["Thiếu khối deny bắt buộc", "Bash(git status) phải viết hoa", "JSON có dấu phẩy thừa sau phần tử cuối nên file không hợp lệ", "File settings.json chỉ được đọc trên CI"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> JSON chuẩn không cho phép dấu phẩy cuối danh sách; file lỗi cú pháp thì không được áp dụng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Khối deny không bắt buộc; tên lệnh không cần viết hoa; settings.json có hiệu lực cả trên máy dev."},
  {"level": 2, "q": "Team dùng Prisma trong <code>packages/db</code>. Lệnh nào nên đặt vào deny cho mọi phiên Claude Code trên máy dev?", "options": ["Bash(pnpm prisma generate) – sinh client", "Bash(pnpm prisma format) – format schema", "Bash(pnpm prisma validate) – kiểm tra schema", "Bash(pnpm prisma migrate reset:*) – xoá sạch dữ liệu database"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> migrate reset drop database rồi chạy lại migration, là hành động phá huỷ nên thuộc nhóm deny.<br><strong>Vì sao các lựa chọn khác sai:</strong> generate, format và validate chỉ tác động cục bộ lên code sinh ra hoặc kiểm tra cú pháp, đảo ngược được nên có thể allow."},
  {"level": 2, "q": "Bạn muốn Claude đọc được code ở thư mục <code>../shared-infra</code> nằm ngoài repo hiện tại. Cấu hình trong permissions nào phù hợp?", "options": ["\"additionalDirectories\": [\"../shared-infra\"]", "\"allow\": [\"Read(*)\"]", "\"env\": { \"EXTRA_DIR\": \"../shared-infra\" }", "\"defaultMode\": \"bypassPermissions\""], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> additionalDirectories mở rộng các thư mục làm việc mà Claude được truy cập ngoài thư mục khởi chạy.<br><strong>Vì sao các lựa chọn khác sai:</strong> Read(*) không mở rộng phạm vi thư mục làm việc một cách tường minh và quá rộng; biến env không cấp quyền; bypassPermissions là quá tay."},
  {"level": 2, "q": "Thứ tự kiểm tra khi Claude gọi <code>Bash(git push origin main)</code> với settings có ask cho <code>Bash(git push:*)</code> và một hook PreToolUse không chặn gì?", "options": ["Rule ask được xét trước, sau khi người dùng đồng ý mới chạy hook", "Hook chỉ chạy khi không có rule nào khớp", "Hook PreToolUse chạy trước, cho qua; sau đó khớp rule ask nên hỏi người dùng", "Lệnh chạy luôn vì hook đã cho qua"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> PreToolUse nằm trước kiểm tra quyền; khi hook không chặn hay tự quyết, luồng tiếp tục xét deny, rồi ask, rồi allow.<br><strong>Vì sao các lựa chọn khác sai:</strong> Rule không được xét trước hook; hook chạy cho mọi lần gọi khớp matcher; hook “cho qua” không đồng nghĩa cấp quyền allow."},
  {"level": 2, "q": "Hook PreToolUse trả JSON sau ra stdout (exit 0):<pre><code>{\n  \"hookSpecificOutput\": {\n    \"hookEventName\": \"PreToolUse\",\n    \"permissionDecision\": \"deny\",\n    \"permissionDecisionReason\": \"Không sửa file trong packages/db/prisma/migrations\"\n  }\n}</code></pre>Kết quả?", "options": ["Tool vẫn chạy vì exit code là 0", "Claude Code hỏi người dùng", "Phiên kết thúc", "Tool bị chặn và lý do được đưa cho Claude"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> PreToolUse có thể tự quyết định quyền qua permissionDecision; giá trị deny chặn lần gọi tool và gửi lý do cho Claude.<br><strong>Vì sao các lựa chọn khác sai:</strong> Exit 0 kèm JSON quyết định vẫn là quyết định chặn; hỏi người dùng tương ứng giá trị ask; hook không kết thúc phiên."},
  {"level": 2, "q": "Bạn muốn một lần chạy Claude Code riêng lẻ dùng chính sách chặt hơn (vd. cho demo khách hàng) mà không sửa file nào trong repo. Cách hợp lý?", "options": ["Chạy với --settings trỏ tới một file JSON chính sách riêng", "Sửa .claude/settings.json rồi revert sau demo", "Sửa ~/.claude/settings.json của đồng nghiệp", "Ghi chính sách vào CLAUDE.md"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> --settings áp settings cho riêng lần chạy đó, không đụng file của team hay của người khác.<br><strong>Vì sao các lựa chọn khác sai:</strong> Sửa rồi revert dễ quên và ảnh hưởng người khác nếu lỡ commit; sửa máy đồng nghiệp là sai phạm vi; CLAUDE.md không cưỡng chế quyền."},
  {"level": 2, "q": "Vì sao nên allow <code>Bash(git diff:*)</code> thay vì <code>Bash(git:*)</code>?", "options": ["git:* không phải cú pháp hợp lệ", "git:* cho phép cả các lệnh ghi như git push, git reset --hard mà không hỏi", "git diff:* chạy nhanh hơn", "Không có khác biệt thực tế"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Rule càng hẹp thì càng ít hành động ngoài ý muốn lọt qua; git diff chỉ đọc còn git:* bao cả lệnh phá huỷ và lệnh ra ngoài.<br><strong>Vì sao các lựa chọn khác sai:</strong> git:* vẫn là tiền tố hợp lệ; rule không ảnh hưởng tốc độ lệnh; phạm vi khác nhau rất lớn nên có khác biệt thực tế."},
  {"level": 2, "q": "Settings ở ba tầng như sau. Claude chạy <code>pnpm deploy:staging</code>, kết quả?<pre><code>// ~/.claude/settings.json\n{ \"permissions\": { \"allow\": [\"Bash(pnpm deploy:*)\"] } }\n\n// .claude/settings.json (team)\n{ \"permissions\": { \"ask\": [\"Bash(pnpm deploy:*)\"] } }</code></pre>", "options": ["Chạy không hỏi vì file user được đọc sau cùng", "Chạy không hỏi vì allow của user ghi đè ask của team", "Bị chặn hẳn", "Hỏi người dùng, vì rule từ mọi tầng được gộp và ask chặt hơn allow"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Danh sách permission gộp từ các tầng; khi lệnh khớp cả allow và ask thì ask thắng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thứ tự đọc file không làm allow thắng; user không ghi đè được rule chặt hơn của team; không có rule deny nào nên không bị chặn hẳn."},
  {"level": 2, "q": "Rule nào chặn Claude sửa bất kỳ file nào trong thư mục migration Prisma bằng các tool sửa file?", "options": ["\"Edit(./packages/db/prisma/migrations/**)\" trong deny", "\"Read(./packages/db/prisma/migrations/**)\" trong deny", "\"Bash(migrations)\" trong ask", "\"Write\" trong allow"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Rule Edit(đường-dẫn) áp cho các tool sửa file; pattern ** khớp mọi file bên trong thư mục.<br><strong>Vì sao các lựa chọn khác sai:</strong> Deny Read chặn đọc chứ không nhắm vào sửa (và làm Claude mất ngữ cảnh); Bash(migrations) không mô tả thao tác sửa file; allow Write làm ngược mục tiêu."},
  {"level": 2, "q": "Một dev commit đoạn sau vào <code>.claude/settings.json</code> của team:<pre><code>{ \"permissions\": { \"defaultMode\": \"acceptEdits\" } }</code></pre>Rủi ro chính là gì?", "options": ["Lệnh git push sẽ không còn bị hỏi", "Mọi người clone repo đều bị tự chấp nhận sửa file, kể cả người mới chưa quen review diff", "Rule deny bị vô hiệu", "Claude không đọc được file nữa"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Mode mặc định là lựa chọn theo mức rủi ro và thói quen từng người; đặt ở file team là áp cho tất cả.<br><strong>Vì sao các lựa chọn khác sai:</strong> acceptEdits chỉ liên quan tới sửa file, không bỏ hỏi git push; deny vẫn có hiệu lực; khả năng đọc file không đổi."},
  {"level": 2, "q": "Bạn cần Claude trong phiên hiện tại tạm dừng sửa file để phân tích kiến trúc <code>apps/api</code> trước. Hành động đúng?", "options": ["Thêm Edit vào deny trong file team", "Xoá quyền ghi thư mục bằng chmod", "Chuyển sang plan mode (vd. bằng Shift+Tab hoặc khởi chạy với --permission-mode plan)", "Ghi vào CLAUDE.md “không được sửa file”"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Plan mode là cơ chế có sẵn để Claude chỉ đọc và đề xuất, bật/tắt nhanh theo phiên.<br><strong>Vì sao các lựa chọn khác sai:</strong> Sửa file team ảnh hưởng mọi người; chmod là thao tác thô và dễ quên khôi phục; CLAUDE.md chỉ là lời dặn, không cưỡng chế."},
  {"level": 2, "q": "Cho <code>.mcp.json</code> của project:<pre><code>{\n  \"mcpServers\": {\n    \"db\": {\n      \"command\": \"node\",\n      \"args\": [\"packages/mcp-db/dist/index.js\"],\n      \"env\": { \"DATABASE_URL\": \"${DATABASE_URL}\" }\n    }\n  }\n}</code></pre>Tool <code>run_sql</code> của server này có tên rule là gì?", "options": ["mcp__db__run_sql", "mcp__mcp-db__run_sql", "db__run_sql", "mcp__DATABASE_URL__run_sql"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Tên server là khoá trong mcpServers (ở đây là db), nên tên tool là mcp__db__run_sql.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tên package hay tên thư mục không phải tên server; thiếu tiền tố mcp__ thì không khớp; tên biến môi trường không liên quan tới tên tool."},
  {"level": 2, "q": "Vì sao nên deny <code>Read(./.mcp.json)</code> khi file này có token viết thẳng thay vì dùng <code>${VAR}</code>?", "options": ["Để MCP server không khởi động được", "Để token không bị đọc vào hội thoại và log phiên; cách tốt hơn là chuyển token ra biến môi trường", "Vì Claude Code không đọc được .mcp.json nếu không deny", "Để .mcp.json tự bị gitignore"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Chặn đọc là lớp phòng thủ thêm; gốc rễ là không đặt secret trong file, dùng ${VAR} mở rộng từ môi trường.<br><strong>Vì sao các lựa chọn khác sai:</strong> Deny Read không ảnh hưởng việc harness khởi động server; Claude Code vẫn nạp cấu hình MCP bình thường; rule quyền không sửa .gitignore."},
  {"level": 2, "q": "Team muốn Claude được gọi <code>WebFetch</code> tới tài liệu NestJS nhưng không tới domain khác. Rule nào đúng?", "options": ["\"WebFetch(*)\" trong allow", "\"Bash(curl docs.nestjs.com)\" trong allow", "\"WebFetch(domain:docs.nestjs.com)\" trong allow", "\"WebFetch\" trong deny kèm \"docs.nestjs.com\" trong env"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> WebFetch hỗ trợ rule theo domain, chỉ tự cho phép đúng domain được liệt kê; các domain khác theo luồng mặc định (hỏi).<br><strong>Vì sao các lựa chọn khác sai:</strong> WebFetch(*) mở cho mọi domain; curl là tool Bash khác; deny WebFetch chặn cả domain mong muốn và env không cấp quyền."},
  {"level": 2, "q": "Đoạn nào là một rule Bash hợp lệ để cho phép mọi lệnh Turborepo chạy test?", "options": ["\"Bash:pnpm turbo run test\"", "\"Turbo(test)\"", "\"Bash[pnpm turbo run test]\"", "\"Bash(pnpm turbo run test:*)\""], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Rule Bash dùng dạng Bash(lệnh) với :* ở cuối để khớp tiền tố.<br><strong>Vì sao các lựa chọn khác sai:</strong> Dùng dấu hai chấm hay ngoặc vuông không đúng cú pháp; không tồn tại tool Turbo."},
  {"level": 2, "q": "Settings có:<pre><code>{ \"permissions\": { \"allow\": [\"Bash(pnpm test:*)\"] } }</code></pre>Claude chạy <code>pnpm test &amp;&amp; git push</code>. Theo thiết kế của Claude Code, lệnh này có được tự chạy không?", "options": ["Có, vì chuỗi bắt đầu bằng pnpm test", "Không, Claude Code nhận biết toán tử nối lệnh nên rule tiền tố không cấp quyền cho cả chuỗi", "Có, nhưng chỉ phần pnpm test chạy", "Không, vì &amp;&amp; luôn bị deny"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Rule tiền tố được thiết kế để không cho “nối đuôi” lệnh khác bằng &&; phần git push vẫn phải qua kiểm tra quyền.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chỉ khớp tiền tố cả chuỗi sẽ là lỗ hổng lớn; Claude Code không cắt lệnh để chạy một nửa; && không bị deny mặc định."},
  {"level": 2, "q": "Trong GitHub Actions, dev dùng cờ sau cho một job review:<pre><code>claude -p \"$PROMPT\" --dangerously-skip-permissions</code></pre>Job chạy trên self-hosted runner có AWS credential quyền admin. Nhận xét đúng?", "options": ["An toàn vì CI không có người dùng", "An toàn vì Claude Code luôn chặn lệnh AWS", "Rất rủi ro: bỏ qua quyền trên máy có credential thật; nên dùng --allowedTools tối thiểu và runner cô lập", "Chỉ rủi ro khi PR từ fork"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Bỏ qua kiểm tra quyền chỉ hợp lý trong môi trường dùng một lần không có secret; self-hosted runner có admin credential thì ngược lại.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có người dùng không làm giảm thiệt hại; không có chặn mặc định lệnh AWS; PR nội bộ cũng có thể chứa prompt injection trong code hoặc issue."},
  {"level": 2, "q": "Settings của team:<pre><code>{\n  \"permissions\": {\n    \"allow\": [\"Read\", \"Bash(git log:*)\"],\n    \"deny\":  [\"Read(./apps/api/.env*)\", \"Read(./apps/web/.env*)\"]\n  }\n}</code></pre>Claude đọc <code>apps/web/.env.local</code> bằng tool Read. Kết quả?", "options": ["Được đọc vì allow \"Read\" bao trùm mọi file", "Hỏi người dùng", "Được đọc vì .env.local không phải .env", "Bị chặn vì khớp Read(./apps/web/.env*) trong deny"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Pattern .env* khớp .env.local; deny thắng allow chung \"Read\".<br><strong>Vì sao các lựa chọn khác sai:</strong> allow rộng không thắng được deny; không có rule ask nào khớp; pattern có dấu * nên bao cả hậu tố .local."},
  {"level": 2, "q": "Cấu hình ở hai tầng:<pre><code>// managed-settings.json (IT cấp)\n{ \"permissions\": { \"deny\": [\"Bash(curl:*)\"] } }\n\n// .claude/settings.local.json (dev tự thêm)\n{ \"permissions\": { \"allow\": [\"Bash(curl:*)\"] } }</code></pre>Claude chạy <code>curl https://api.example.com</code>. Kết quả?", "options": ["curl vẫn bị chặn vì deny ở managed không thể bị ghi đè bởi allow ở tầng dưới", "curl được chạy vì local ưu tiên hơn project", "Claude Code báo lỗi và không khởi động", "curl bị hỏi thay vì chặn"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Rule được gộp và deny thắng allow; thêm nữa managed là tầng cao nhất nên chính sách công ty luôn giữ nguyên.<br><strong>Vì sao các lựa chọn khác sai:</strong> Ưu tiên local > project không giúp allow thắng deny; cấu hình mâu thuẫn không làm hỏng khởi động; deny không bị hạ xuống ask."},
  {"level": 2, "q": "Monorepo có <code>apps/api</code> (NestJS) và <code>apps/web</code> (Next.js). Team muốn allow chạy test của cả hai qua Turborepo nhưng không allow <code>turbo run deploy</code>. Rule tốt nhất?", "options": ["allow \"Bash(pnpm turbo:*)\" rồi deny \"Bash(pnpm turbo run test:*)\"", "allow \"Bash(pnpm:*)\"", "allow \"Bash(pnpm turbo run test:*)\", \"Bash(pnpm turbo run lint:*)\"; không allow tiền tố \"Bash(pnpm turbo:*)\"", "deny \"Bash(pnpm turbo run test:*)\""], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Liệt kê cụ thể các task an toàn giữ deploy nằm ngoài allow, nên vẫn bị hỏi theo luồng mặc định.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tiền tố turbo:* cho phép cả deploy, lại còn deny chính task test; pnpm:* quá rộng; deny test làm ngược mục tiêu."},
  {"level": 2, "q": "Vì sao khuyên allow lệnh chỉ đọc trước khi nghĩ tới <code>acceptEdits</code>?", "options": ["acceptEdits không tồn tại trong Claude Code", "Allow lệnh đọc tự động bật acceptEdits", "acceptEdits chặn các lệnh đọc", "Allow lệnh chỉ đọc giảm phần lớn số lần hỏi mà không cho thêm quyền thay đổi gì"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Đa số lần hỏi đến từ lệnh xem trạng thái như git status, ls, test; allow chúng là cách ít rủi ro nhất để làm việc trơn tru.<br><strong>Vì sao các lựa chọn khác sai:</strong> acceptEdits là mode có thật; allow không tự bật mode; acceptEdits không chặn lệnh đọc."},
  {"level": 2, "q": "Bạn muốn biết rule nào đang làm lệnh <code>pnpm prisma studio</code> bị hỏi. Cách nhanh nhất?", "options": ["Gõ /permissions trong phiên để xem các rule đang được nạp và nguồn của chúng", "Đọc lại toàn bộ lịch sử git của repo", "Xoá hết settings rồi thêm lại từng dòng", "Hỏi Claude đoán xem rule nào"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> /permissions liệt kê rule hiện hành, giúp truy ra tầng settings chứa rule gây hỏi.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lịch sử git không bao gồm settings user/managed; xoá hết là thao tác phá; model đoán không chính xác bằng xem cấu hình thật."},
  {"level": 2, "q": "Một dev commit đoạn sau vào <code>.claude/settings.json</code> “để team đỡ phải cấu hình”:<pre><code>{\n  \"env\": { \"ANTHROPIC_API_KEY\": \"sk-ant-api03-xxxxxxxx\" }\n}</code></pre>Vấn đề là gì?", "options": ["Khối env không hỗ trợ biến tên ANTHROPIC_API_KEY", "File này được commit nên key bị lộ trong repo và lịch sử git; nên dùng biến môi trường hoặc cơ chế lấy key động", "Claude Code sẽ tự mã hoá key", "Không có vấn đề nếu repo private"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Secret trong file commit coi như đã lộ cho mọi người có quyền đọc repo, fork và backup; nên để ở secret store hoặc env cá nhân.<br><strong>Vì sao các lựa chọn khác sai:</strong> Khối env nhận tên biến bất kỳ; Claude Code không mã hoá giá trị; repo private vẫn có nhiều người và hệ thống đọc được."},
  {"level": 2, "q": "Settings có đoạn:<pre><code>{\n  \"apiKeyHelper\": \"aws secretsmanager get-secret-value --secret-id dev/claude/api-key --query SecretString --output text\"\n}</code></pre>Công dụng hợp lý nhất của khoá <code>apiKeyHelper</code> ở đây?", "options": ["Tạo API key mới trên Console mỗi lần chạy", "Mã hoá toàn bộ settings.json", "Chặn Claude đọc biến môi trường", "Chỉ định một script in ra API key, vd. script lấy key từ AWS Secrets Manager thay vì lưu key trong file"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> apiKeyHelper cho phép lấy credential động bằng một lệnh shell, phù hợp khi key nằm trong secret store.<br><strong>Vì sao các lựa chọn khác sai:</strong> Nó không tự cấp key mới trên Console; không mã hoá settings; không liên quan tới việc chặn đọc env."},
  {"level": 2, "q": "PR review bot dùng Claude Code headless. Cấu hình <code>--allowedTools</code> nào hợp lý nhất cho tác vụ “đọc diff, chạy lint, viết nhận xét ra stdout”?", "options": ["\"Read,Grep,Glob,Bash(git diff:*),Bash(pnpm lint:*)\"", "\"Bash,Edit,Write\"", "\"Read,Edit,Bash(git push:*)\"", "Không truyền cờ, dùng --dangerously-skip-permissions"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Chỉ cấp đúng các tool đọc và lệnh cần thiết theo nguyên tắc quyền tối thiểu.<br><strong>Vì sao các lựa chọn khác sai:</strong> Bash trần và Edit/Write cho phép sửa và chạy mọi thứ; git push không cần cho việc review; bỏ qua quyền là quá rủi ro trên CI."},
  {"level": 2, "q": "Để tìm lỗi trong đoạn settings dưới đây, nhận xét nào đúng?<pre><code>{\n  \"permission\": {\n    \"deny\": [\"Read(./.env)\"]\n  }\n}</code></pre>", "options": ["Thiếu khối allow bắt buộc", "Khoá phải là \"permissions\" (số nhiều); khoá sai tên nên rule không có tác dụng", "Đường dẫn phải là tuyệt đối", "deny chỉ nhận lệnh Bash"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Claude Code đọc rule trong khối permissions; khoá permission không được nhận ra nên deny không hoạt động.<br><strong>Vì sao các lựa chọn khác sai:</strong> allow không bắt buộc; đường dẫn tương đối ./ là hợp lệ; deny nhận mọi loại tool, không riêng Bash."},
  {"level": 2, "q": "Người mới trong team hỏi: “Sao tôi không xoá được rule deny <code>Bash(aws s3 rm:*)</code> dù đã sửa hết file settings của mình?”. Giải thích hợp lý nhất?", "options": ["Claude Code cache settings vĩnh viễn", "Rule deny không bao giờ xoá được", "Rule nằm trong managed settings do IT cấp, người dùng không ghi đè được", "Phải xoá CLAUDE.md trước"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Nếu không tìm thấy rule trong file user/project/local thì rất có thể nó đến từ tầng managed.<br><strong>Vì sao các lựa chọn khác sai:</strong> Settings được nạp lại khi khởi động phiên; deny ở file do bạn quản lý thì vẫn xoá được; CLAUDE.md không chứa rule quyền."},
  {"level": 2, "q": "Trong một repo Next.js, bạn muốn cho Claude sửa <code>apps/web/**</code> thoải mái nhưng mọi thao tác sửa <code>infra/terraform/**</code> đều phải hỏi. Cấu hình phù hợp?", "options": ["ask [\"Edit(./infra/terraform/**)\"] (kèm acceptEdits hoặc allow Edit cho phần còn lại nếu muốn)", "deny [\"Edit(./apps/web/**)\"]", "allow [\"Edit(./infra/terraform/**)\"]", "ask [\"Read(./infra/terraform/**)\"]"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> ask theo đường dẫn giữ con người trong vòng lặp cho vùng hạ tầng, trong khi app code được sửa nhanh.<br><strong>Vì sao các lựa chọn khác sai:</strong> deny apps/web làm ngược mục tiêu; allow terraform bỏ bước xác nhận; ask Read nhắm vào đọc chứ không phải sửa."},
  {"level": 2, "q": "Đâu là dấu hiệu nên chuyển một lệnh từ allow sang ask?", "options": ["Lệnh chạy lâu hơn 5 giây", "Lệnh có thể tác động ra ngoài máy, vd. gửi dữ liệu lên S3 hay publish package", "Lệnh có nhiều tham số", "Lệnh được gọi nhiều lần"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Tiêu chí chính là tác động và khả năng đảo ngược, không phải thời gian hay tần suất.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thời gian chạy, số tham số và tần suất gọi không phản ánh rủi ro của hành động."},
  {"level": 2, "q": "Một dev muốn bật <code>acceptEdits</code> chỉ cho riêng mình ở mọi project. Nơi đặt hợp lý?", "options": [".claude/settings.json của từng repo", "Managed settings", "~/.claude/settings.json với permissions.defaultMode", ".mcp.json"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Thói quen cá nhân áp cho mọi project thuộc tầng user.<br><strong>Vì sao các lựa chọn khác sai:</strong> File project áp cho cả team; managed là chính sách tổ chức; .mcp.json chỉ khai báo MCP server."},
  {"level": 2, "q": "Hook PreToolUse có thể làm gì mà rule permission tĩnh không làm được?", "options": ["Chạy sau khi tool đã hoàn tất", "Thay thế hoàn toàn managed settings", "Tăng giới hạn token của model", "Kiểm tra động nội dung input (vd. phân tích câu SQL hay đường dẫn) rồi chặn, sửa input hoặc tự quyết quyền"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Hook là code nên có thể áp logic tuỳ ý trên tool_input, ví dụ chặn câu lệnh DROP TABLE trong input của tool MCP.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chạy sau tool là PostToolUse; hook không thay thế cơ chế managed; hook không liên quan giới hạn token."},
  {"level": 2, "q": "Settings có:<pre><code>{\n  \"permissions\": {\n    \"ask\":  [\"mcp__db\"],\n    \"allow\": [\"mcp__db__list_tables\"]\n  }\n}</code></pre>Claude gọi <code>mcp__db__list_tables</code>. Kết quả?", "options": ["Chạy không hỏi vì rule allow cụ thể hơn", "Hỏi người dùng, vì tool khớp rule ask của cả server và ask chặt hơn allow", "Bị chặn", "Lỗi vì hai rule chồng nhau"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> mcp__db khớp mọi tool của server db; khi khớp cả ask lẫn allow thì ask thắng, không xét rule nào “cụ thể hơn”.<br><strong>Vì sao các lựa chọn khác sai:</strong> Độ cụ thể không phải tiêu chí phân xử; không có deny nên không bị chặn; rule chồng nhau là hợp lệ."},
  {"level": 2, "q": "Bạn muốn test nhanh xem rule mới trong settings.json đã có hiệu lực chưa. Cách kiểm chứng đúng?", "options": ["Chỉ cần lưu file, không cần kiểm tra", "Chạy node --check trên file JSON", "Mở phiên mới, xem /permissions, rồi yêu cầu Claude thực hiện đúng hành động bị chặn/cho phép", "Commit lên main và chờ CI"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Kiểm chứng cả ở tầng cấu hình (rule đã nạp) và hành vi thật (bị chặn hay được chạy).<br><strong>Vì sao các lựa chọn khác sai:</strong> Không kiểm tra thì lỗi cú pháp hay sai đường dẫn khó phát hiện; node --check dành cho JS; CI không kiểm tra hành vi quyền trên máy bạn."},
  {"level": 3, "q": "Công ty outsource 150 dev làm monorepo NestJS/Next.js cho khách hàng tài chính. Yêu cầu: không ai được chạy <code>aws</code> CLI với profile production qua Claude Code, dev vẫn tự thêm allow cho lệnh test. Thiết kế nào đúng?<pre><code>{\n  \"permissions\": {\n    \"deny\": [\"Bash(aws --profile prod:*)\", \"Bash(AWS_PROFILE=prod:*)\"]\n  }\n}</code></pre>", "options": ["Đặt đoạn này vào .claude/settings.json của từng repo", "Ghi yêu cầu vào CLAUDE.md gốc", "Đặt vào ~/.claude/settings.json trên máy mỗi dev bằng hướng dẫn nội bộ", "Phát hành đoạn này dưới dạng managed settings; dev tự thêm allow ở settings.local.json"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Managed settings có ưu tiên cao nhất, không bị ghi đè, áp đồng nhất mọi máy; allow ở tầng dưới vẫn được gộp nhưng không thắng deny.<br><strong>Vì sao các lựa chọn khác sai:</strong> File project có thể bị sửa trong repo mới; CLAUDE.md không cưỡng chế; file user do chính dev kiểm soát nên xoá được."},
  {"level": 3, "q": "Pipeline GitHub Actions chạy Claude Code review mọi PR, kể cả PR từ fork công khai. Mô tả PR có thể chứa prompt injection. Cấu hình nào an toàn nhất?", "options": ["Chỉ allow tool đọc và git diff, không cấp secret ngoài API key, không cấp tool ghi hay mạng, output chỉ là JSON để bước sau đăng comment", "Cho Claude tự đăng comment bằng gh với GITHUB_TOKEN quyền write-all", "Dùng bypassPermissions vì runner là ephemeral", "Allow Bash(*) nhưng deny rm -rf"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Quyền tối thiểu cộng tách biệt bước “suy luận” và bước “hành động” giới hạn thiệt hại nếu model bị thao túng bởi nội dung PR.<br><strong>Vì sao các lựa chọn khác sai:</strong> Token write-all cho phép hành động rộng khi bị injection; runner ephemeral vẫn có API key và token; Bash(*) với một deny là blocklist rất yếu."},
  {"level": 3, "q": "Team muốn chặn mọi câu SQL có <code>DROP</code> hoặc <code>TRUNCATE</code> gửi qua tool <code>mcp__db__run_sql</code>, nhưng vẫn cho SELECT không cần hỏi. Giải pháp nào đúng?", "options": ["deny mcp__db__run_sql", "ask mcp__db__run_sql cho mọi câu", "Allow mcp__db__run_sql và thêm hook PreToolUse matcher mcp__db__run_sql phân tích tool_input.sql, chặn câu nguy hiểm", "Ghi quy tắc vào mô tả tool trong MCP server"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Rule tĩnh chỉ khớp tên tool, không nhìn nội dung input; hook PreToolUse chạy trước kiểm tra quyền và lọc được theo nội dung.<br><strong>Vì sao các lựa chọn khác sai:</strong> deny chặn luôn SELECT; ask cho mọi câu gây mệt mỏi xác nhận; mô tả tool chỉ là gợi ý cho model, không cưỡng chế."},
  {"level": 3, "q": "Dev báo: “Tôi đã deny <code>Read(./.env)</code> nhưng log phiên vẫn thấy DATABASE_URL.” Kiểm tra nhanh thấy Claude đã chạy <code>pnpm prisma migrate status</code> và lệnh này in URL ra stdout. Biện pháp đúng gốc nhất?", "options": ["Thêm deny Read(./.env) lần nữa ở settings.local.json", "Chuyển sang plan mode vĩnh viễn", "Tắt log phiên", "Không đặt secret production trên máy dev; dùng database dev/ephemeral và lấy credential theo phiên, kết hợp deny/ask các lệnh in cấu hình"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Rule chặn một đường đọc nhưng secret có thể lọt qua nhiều đường khác; giảm secret có trên máy là giải pháp gốc, rule là lớp bổ sung.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lặp lại rule không chặn đường qua Bash; plan mode vẫn chạy được lệnh đọc; tắt log không ngăn secret vào context của model."},
  {"level": 3, "q": "Công ty dùng Claude Code qua Amazon Bedrock. Cần mọi dev dùng Bedrock (không dùng API trực tiếp) và không tự đổi được. Cách hợp lý?", "options": ["Đặt biến CLAUDE_CODE_USE_BEDROCK và region trong khối env của managed settings, kèm IAM role giới hạn model được gọi", "Ghi vào CLAUDE.md “luôn dùng Bedrock”", "Đặt biến trong .claude/settings.local.json của từng repo", "Yêu cầu dev export biến trong .zshrc"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Managed settings áp và giữ cố định cấu hình cho mọi máy; IAM ở phía AWS là lớp kiểm soát thứ hai. Tên biến cụ thể nên kiểm tra tài liệu mới nhất.<br><strong>Vì sao các lựa chọn khác sai:</strong> CLAUDE.md không điều khiển kết nối; settings.local.json và .zshrc do dev tự sửa được."},
  {"level": 3, "q": "Workflow sau dùng để sinh changelog. Vấn đề bảo mật lớn nhất là gì?<pre><code>jobs:\n  changelog:\n    runs-on: ubuntu-latest\n    permissions: write-all\n    steps:\n      - uses: actions/checkout@v4\n      - run: |\n          npx @anthropic-ai/claude-code -p \"Viết CHANGELOG cho release\" \\\n            --allowedTools \"Bash\" --output-format json\n        env:\n          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}\n          AWS_ACCESS_KEY_ID: ${{ secrets.PROD_AWS_KEY }}</code></pre>", "options": ["Dùng ubuntu-latest thay vì macOS", "Cấp Bash không giới hạn cùng token write-all và AWS key production, trong khi tác vụ chỉ cần đọc git log và ghi một file", "Thiếu cờ --verbose", "Dùng actions/checkout@v4"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Tác vụ chỉ cần Read, Bash(git log:*) và Edit/Write cho CHANGELOG; mọi credential thừa đều làm tăng thiệt hại khi có sự cố.<br><strong>Vì sao các lựa chọn khác sai:</strong> Hệ điều hành runner, cờ verbose và phiên bản checkout không phải rủi ro chính."},
  {"level": 3, "q": "Bạn cần cho Claude chạy trong CI một lệnh sửa code tự động (codemod) trên nhánh bot, mở PR để người review. Chọn cấu hình cân bằng nhất?", "options": ["bypassPermissions và token admin để bot tự merge", "plan mode để không sửa được gì", "Allow Bash và Edit toàn repo, cho bot push thẳng lên main", "--allowedTools \"Read,Edit,Write,Bash(pnpm codemod:*),Bash(pnpm test:*)\"; tạo PR ở bước riêng bằng token chỉ có quyền contents và pull-requests"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Cho đủ quyền sửa file và chạy test để hoàn thành việc, còn thao tác ra ngoài (tạo PR) nằm ở bước riêng với token hẹp, con người review trước khi merge.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tự merge bằng token admin bỏ qua review; plan mode không làm được codemod; push thẳng main loại bỏ lớp kiểm soát con người."},
  {"level": 3, "q": "Settings của team và của một dev như sau. Dev chạy <code>claude --settings demo.json</code>. Claude chạy <code>git push</code>, kết quả?<pre><code>// .claude/settings.json\n{ \"permissions\": { \"ask\": [\"Bash(git push:*)\"] } }\n\n// demo.json\n{ \"permissions\": { \"allow\": [\"Bash(git push:*)\"] } }</code></pre>", "options": ["Vẫn hỏi, vì rule ask ở file team vẫn được gộp và ask chặt hơn allow", "Chạy không hỏi vì --settings ưu tiên cao hơn project", "Bị chặn hẳn", "demo.json thay thế hoàn toàn settings.json"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Thứ tự ưu tiên quyết định giá trị cho các khoá đơn, còn danh sách permission gộp và rule chặt nhất thắng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Ưu tiên cao hơn không làm allow thắng ask; không có deny; --settings không loại bỏ file project."},
  {"level": 3, "q": "Một agent nội bộ dùng Claude Agent SDK/Claude Code chạy trên ECS Fargate để xử lý ticket, có quyền đọc RDS. Kiểm soát nào đặt ở đâu là hợp lý nhất?", "options": ["Chỉ cần viết system prompt “không được xoá dữ liệu”", "IAM task role và user DB chỉ đọc ở tầng AWS; allowlist tool trong cấu hình agent; hook PreToolUse lọc input nhạy cảm", "Cấp quyền admin RDS nhưng deny DROP trong prompt", "Để model tự đánh giá rủi ro mỗi lần"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Phòng thủ nhiều lớp: giới hạn ở hạ tầng không phụ thuộc model, rồi mới tới cấu hình quyền và hook.<br><strong>Vì sao các lựa chọn khác sai:</strong> Prompt không cưỡng chế; quyền admin khiến sai sót có hậu quả lớn; model tự đánh giá không phải cơ chế kiểm soát."},
  {"level": 3, "q": "Settings của team:<pre><code>{\n  \"permissions\": {\n    \"ask\": [\"Bash(git status)\", \"Bash(ls:*)\", \"Bash(pnpm test:*)\",\n            \"Bash(git diff:*)\", \"Bash(git push:*)\"]\n  }\n}</code></pre>Dev bấm “cho phép” theo phản xạ, kể cả khi Claude chạy <code>git push --force</code>. Cải thiện nào tốt nhất?", "options": ["Chuyển tất cả sang ask để chắc chắn", "Chuyển tất cả sang allow", "Allow rộng rãi lệnh chỉ đọc/test, deny hẳn git push --force, chỉ để ask cho số ít hành động ra ngoài quan trọng", "Huấn luyện dev đọc kỹ hơn, giữ nguyên cấu hình"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Giảm số lần hỏi vô nghĩa làm mỗi câu hỏi còn lại có trọng lượng; hành động không bao giờ nên xảy ra thì deny thay vì trông vào người bấm.<br><strong>Vì sao các lựa chọn khác sai:</strong> Ask tất cả làm mệt mỏi nặng hơn; allow tất cả bỏ kiểm soát; chỉ nhắc nhở không sửa được nguyên nhân gốc."},
  {"level": 3, "q": "Bạn dựng MCP server nội bộ đọc log CloudWatch cho team. Tool <code>get_logs</code> có thể trả về PII của khách hàng. Kết hợp nào hợp lý?", "options": ["Server tự che PII trước khi trả kết quả, IAM role chỉ đọc log group cần thiết, rule allow mcp__cw__get_logs cho team", "Allow và tin model sẽ không nhắc PII", "deny mcp__cw để an toàn tuyệt đối", "Ghi cảnh báo PII vào CLAUDE.md"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Dữ liệu nhạy cảm nên được xử lý ở phía server trước khi vào context; IAM giới hạn phạm vi; rule allow giúp dùng trơn tru.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tin model là không đủ; deny cả server làm mất giá trị công cụ; CLAUDE.md không ngăn dữ liệu đi vào context."},
  {"level": 3, "q": "Headless job trả về JSON sau khi dùng <code>--output-format json</code>. Bước tiếp theo trong workflow nên kiểm tra gì trước khi đăng comment lên PR?<pre><code>{\n  \"type\": \"result\",\n  \"subtype\": \"success\",\n  \"is_error\": false,\n  \"result\": \"## Review\\n- apps/api/src/orders/orders.service.ts: ...\",\n  \"total_cost_usd\": 0.41,\n  \"session_id\": \"...\"\n}</code></pre>", "options": ["Chỉ cần kiểm tra session_id khác rỗng", "is_error là false rồi mới dùng trường result; có thể đặt ngưỡng cảnh báo theo total_cost_usd", "Parse result như JSON bắt buộc", "Bỏ qua kiểm tra vì exit code luôn là 0"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Kiểm tra trạng thái lỗi trước khi hành động tránh đăng rác lên PR; theo dõi chi phí giúp phát hiện prompt chạy vòng lặp dài.<br><strong>Vì sao các lựa chọn khác sai:</strong> session_id không cho biết thành công; result ở đây là markdown, không phải JSON; không nên giả định exit code luôn 0 mà bỏ qua kiểm tra."},
  {"level": 3, "q": "Doanh nghiệp yêu cầu: dev không được bật chế độ bỏ qua quyền trên máy công ty. Giải pháp phù hợp?", "options": ["Ghi chú trong wiki nội bộ", "Deny \"Bash(*)\" trong settings.json của mọi repo", "Managed settings với \"permissions\": { \"disableBypassPermissionsMode\": \"disable\" }", "Xoá cờ khỏi tài liệu onboarding"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Tuỳ chọn này trong managed settings ngăn người dùng kích hoạt bypassPermissions; managed không bị ghi đè.<br><strong>Vì sao các lựa chọn khác sai:</strong> Wiki và tài liệu không cưỡng chế; deny Bash(*) chặn luôn công việc bình thường và vẫn không vô hiệu hoá cờ."},
  {"level": 3, "q": "Hai phương án để chặn sửa file migration Prisma: (1) rule <code>deny Edit(./packages/db/prisma/migrations/**)</code>; (2) hook PreToolUse exit 2 kèm thông điệp “hãy sửa schema.prisma rồi chạy prisma migrate dev”. Nhận xét đúng?", "options": ["Chỉ rule mới chặn được, hook chỉ ghi log", "Chỉ hook chặn được, rule deny không áp cho Edit", "Hai phương án loại trừ nhau, không dùng chung được", "Cả hai đều chặn được; hook còn hướng dẫn Claude đi đúng quy trình, còn rule đơn giản và dễ kiểm tra hơn – có thể dùng cả hai"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Rule là chặn tĩnh, rõ ràng; hook exit 2 chặn và đưa stderr cho Claude nên model biết cách làm đúng. Kết hợp cho phòng thủ nhiều lớp.<br><strong>Vì sao các lựa chọn khác sai:</strong> Hook PreToolUse exit 2 thực sự chặn tool; deny Edit có áp cho tool sửa file; hai cơ chế độc lập và bổ trợ nhau."},
  {"level": 3, "q": "Next.js app gọi Claude qua route handler; dev dùng Claude Code để sửa. Yêu cầu bảo mật: Claude Code không được đọc <code>apps/web/.env.local</code> chứa ANTHROPIC_API_KEY, nhưng app vẫn cần key khi chạy <code>pnpm dev</code>. Phương án tốt nhất?<pre><code>{\n  \"permissions\": {\n    \"deny\": [\"Read(./apps/web/.env*)\", \"Bash(cat apps/web/.env*)\"],\n    \"allow\": [\"Bash(pnpm --filter web dev)\"]\n  }\n}</code></pre>", "options": ["Không làm được: deny Read sẽ khiến Next.js không đọc được .env", "Giữ deny đọc file env cho Claude; tiến trình pnpm dev vẫn nạp env bình thường vì rule chỉ áp cho tool của Claude", "Phải chép key vào CLAUDE.md để Claude biết", "Phải chuyển key vào next.config.js"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Permission rule kiểm soát tool của Claude, không kiểm soát tiến trình Node đang chạy app. Rule Bash theo chuỗi lệnh dễ bị lách bằng cách viết lệnh khác (head, grep…), nên thực tế cần thêm hook PreToolUse để lọc lệnh đọc env.<br><strong>Vì sao các lựa chọn khác sai:</strong> Next.js không bị ảnh hưởng bởi rule của Claude Code; chép key vào CLAUDE.md hay next.config.js là làm lộ key."},
  {"level": 3, "q": "Một đội muốn cho Claude tự <code>git commit</code> nhưng luôn hỏi trước <code>git push</code>, và tuyệt đối không <code>git push --force</code>. Cấu hình đúng?<pre><code>{\n  \"permissions\": {\n    \"allow\": [\"Bash(git add:*)\", \"Bash(git commit:*)\"],\n    \"ask\":   [\"Bash(git push:*)\"],\n    \"deny\":  [\"Bash(git push --force:*)\", \"Bash(git push -f:*)\"]\n  }\n}</code></pre>", "options": ["Sai: force push sẽ bị hỏi vì khớp ask trước", "Sai: phải đặt deny lên đầu file", "Đúng: commit tự chạy, push bị hỏi, force push bị chặn vì deny thắng ask", "Sai: git commit cần nằm trong ask"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> git push --force khớp cả ask và deny; deny chặt nhất nên thắng. Thứ tự khối trong JSON không quan trọng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có khái niệm “khớp trước”; vị trí khối không ảnh hưởng; commit là thao tác cục bộ đảo ngược được nên allow hợp lý."},
  {"level": 3, "q": "Bạn cần chạy Claude Code headless trên Lambda (container image) để tóm tắt log lỗi đẩy từ SQS. Lựa chọn nào hợp lý về quyền?", "options": ["bypassPermissions vì Lambda là môi trường cô lập", "Allow Bash để Claude tự gọi aws CLI ghi kết quả", "Cấp AdministratorAccess cho role để tránh lỗi quyền", "Chỉ allow Read và tool MCP đọc log; không cấp Bash; Lambda role chỉ đọc log group cần thiết; kết quả đưa về SQS/S3 bằng code của bạn"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Môi trường cô lập không có nghĩa không có credential; phần hành động ra ngoài nên do code xác định chứ không để model tự gọi CLI.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lambda vẫn có role và quyền mạng; Bash + aws CLI mở phạm vi quá rộng; AdministratorAccess vi phạm quyền tối thiểu."},
  {"level": 3, "q": "Trong đề thi: “Kỹ sư muốn thử nghiệm rule mới cho riêng mình trước khi đề xuất cho team, không muốn đồng đội bị ảnh hưởng, và không muốn commit nhầm.” Đáp án đúng?", "options": ["Viết rule vào .claude/settings.local.json (được gitignore), thử, rồi mở PR sửa .claude/settings.json", "Sửa trực tiếp .claude/settings.json trên main", "Ghi rule vào CLAUDE.md", "Yêu cầu IT thêm vào managed settings để thử"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Tầng local đúng phạm vi “chỉ mình tôi, trong project này”, sau đó đề xuất qua PR để team review.<br><strong>Vì sao các lựa chọn khác sai:</strong> Sửa main ảnh hưởng mọi người; CLAUDE.md không phải rule; managed là chính sách tổ chức, quá nặng để thử nghiệm."},
  {"level": 3, "q": "Hook PreToolUse được đăng ký như sau, script gọi API nội bộ kiểm tra chính sách mất 8 giây mỗi lần:<pre><code>{ \"hooks\": { \"PreToolUse\": [ { \"matcher\": \".*\",\n  \"hooks\": [ { \"type\": \"command\", \"command\": \"node scripts/policy-check.js\" } ] } ] } }</code></pre>Dev phàn nàn mọi thao tác đều chậm. Cách tối ưu hợp lý?", "options": ["Xoá hook và thay bằng lời dặn trong CLAUDE.md", "Tăng timeout hook lên 10 phút", "Thu hẹp matcher chỉ vào tool/lệnh cần kiểm tra, cache quyết định, và chuyển phần kiểm tra tĩnh sang rule deny/allow", "Chạy hook ở PostToolUse cho nhanh"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Rule tĩnh được xử lý ngay, hook chỉ nên dùng cho logic động; matcher hẹp và cache giảm độ trễ mà vẫn giữ kiểm soát.<br><strong>Vì sao các lựa chọn khác sai:</strong> CLAUDE.md mất tính cưỡng chế; tăng timeout làm chậm hơn; PostToolUse chạy sau tool nên không chặn được nữa."},
  {"level": 3, "q": "Cho cấu hình dưới đây trong repo công khai. Rủi ro nào lớn nhất?<pre><code>// .mcp.json (commit)\n{\n  \"mcpServers\": {\n    \"github\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"@modelcontextprotocol/server-github\"],\n      \"env\": { \"GITHUB_PERSONAL_ACCESS_TOKEN\": \"ghp_xxxREALTOKENxxx\" }\n    }\n  }\n}</code></pre>", "options": ["Thiếu rule allow cho mcp__github", "npx -y làm chậm khởi động", "Tên server phải viết hoa", "Token thật bị commit công khai; phải thu hồi ngay và đổi sang \"${GITHUB_TOKEN}\" lấy từ môi trường"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> .mcp.json hỗ trợ mở rộng ${VAR}; secret phải lấy từ môi trường hoặc secret store, token đã lộ thì phải thu hồi chứ không chỉ xoá commit.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thiếu rule allow chỉ gây hỏi quyền; tốc độ npx không phải vấn đề bảo mật; tên server không cần viết hoa."},
  {"level": 3, "q": "Sếp yêu cầu “Claude Code chỉ được truy cập internet tới registry npm nội bộ và GitHub”. Phương án có tính cưỡng chế nhất?", "options": ["Kiểm soát mạng ở tầng hạ tầng (proxy/sandbox/firewall) kết hợp managed settings deny các lệnh tải từ domain khác", "Viết vào CLAUDE.md danh sách domain được phép", "Chỉ dùng rule WebFetch theo domain, không kiểm soát Bash", "Tin rằng Claude sẽ không tải từ nơi lạ"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Rule WebFetch không bao được curl, npm hay script Node tự mở kết nối; chặn ở tầng mạng không phụ thuộc tool nào được dùng.<br><strong>Vì sao các lựa chọn khác sai:</strong> CLAUDE.md và niềm tin vào model không cưỡng chế; chỉ WebFetch là thiếu vì còn nhiều đường ra mạng khác."},
  {"level": 3, "q": "Đoạn settings sau dùng cho job CI chạy nightly “dọn dead code”:<pre><code>{\n  \"permissions\": {\n    \"defaultMode\": \"acceptEdits\",\n    \"allow\": [\"Bash(pnpm turbo run test:*)\", \"Bash(pnpm knip:*)\"],\n    \"deny\": [\"Bash(git push:*)\", \"Read(./**/.env*)\"]\n  }\n}</code></pre>Job xong sẽ để bước sau tạo PR. Nhận xét nào đúng?", "options": ["Sai vì acceptEdits cho phép push", "Hợp lý: được sửa file và chạy công cụ phân tích/test, không tự push, không đọc env; PR do bước riêng tạo", "Sai vì deny Read(./**/.env*) chặn luôn tất cả file", "Sai vì knip phải nằm trong ask"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Cấu hình cho đúng quyền cần để hoàn thành việc và giữ các hành động ra ngoài cho bước có kiểm soát.<br><strong>Vì sao các lựa chọn khác sai:</strong> acceptEdits không liên quan tới push; pattern chỉ khớp file .env*; knip chỉ phân tích code nên allow là hợp lý."},
  {"level": 3, "q": "Bạn phát hiện một dev đã thêm rule allow <code>mcp__prod_db</code> vào settings.json của team để “tiện debug”. Đánh giá theo kiểu đề thi?", "options": ["Chấp nhận vì MCP server luôn chỉ đọc", "Chấp nhận vì chỉ dev mới dùng Claude Code", "Chuyển rule sang CLAUDE.md", "Nên thay bằng ask hoặc gỡ bỏ, và cân nhắc chặn server này ở managed settings nếu truy cập production không được phép"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Truy cập production là hành động rủi ro cao, không nên được tự động cho phép cho cả team; chính sách tổ chức nên đặt ở managed.<br><strong>Vì sao các lựa chọn khác sai:</strong> MCP server có thể có tool ghi; “chỉ dev dùng” không giảm rủi ro; CLAUDE.md không phải cơ chế quyền."},
  {"level": 3, "q": "Một task chạy <code>claude -p</code> trong GitHub Actions cần đọc secret từ AWS Secrets Manager để gọi Claude API. Cách tốt nhất?", "options": ["Dùng OIDC (aws-actions/configure-aws-credentials) với role chỉ được GetSecretValue secret đó, đọc key ở bước riêng rồi truyền qua env, che log", "Lưu access key dài hạn của IAM user admin trong GitHub secrets", "Cho Claude tự chạy aws secretsmanager get-secret-value", "Commit key vào .claude/settings.json"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> OIDC tránh credential dài hạn, role hẹp giới hạn phạm vi; bước lấy secret nằm ngoài quyền của Claude.<br><strong>Vì sao các lựa chọn khác sai:</strong> Access key admin dài hạn là rủi ro lớn; để Claude tự lấy secret đưa secret vào context; commit key là lộ key."},
  {"level": 3, "q": "Giám đốc kỹ thuật hỏi: “Đặt quy tắc ‘không sửa thư mục packages/shared/generated’ ở đâu để hiệu quả nhất?” Code trong đó sinh từ OpenAPI. Câu trả lời tốt nhất?", "options": ["Chỉ ghi vào CLAUDE.md", "Rule deny Edit cho thư mục đó trong settings.json của team, cộng hook PreToolUse báo “chạy pnpm gen:api thay vì sửa tay”", "Thêm thư mục vào .gitignore", "Deny Read cho thư mục đó"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Rule cưỡng chế việc không sửa; hook cung cấp chỉ dẫn để Claude chọn đường đúng. Đây là kết hợp “chặn + hướng dẫn”.<br><strong>Vì sao các lựa chọn khác sai:</strong> CLAUDE.md có thể bị bỏ qua; gitignore code sinh có thể phá build và không chặn sửa; deny Read làm Claude mất ngữ cảnh kiểu dữ liệu cần dùng."},
  {"level": 3, "q": "Nhóm platform muốn thống kê những lệnh Claude hay bị hỏi quyền nhất trong toàn công ty để tối ưu allowlist. Cách tiếp cận hợp lý?", "options": ["Hỏi từng dev nhớ lại", "Bật bypassPermissions để không cần thống kê", "Dùng hook (vd. PermissionRequest/PreToolUse) ghi sự kiện ra log tập trung như CloudWatch, phân tích định kỳ rồi cập nhật rule", "Đọc CLAUDE.md của từng repo"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Hook nhận dữ liệu sự kiện JSON nên có thể ghi log tự động và đầy đủ, là nguồn dữ liệu tốt để tinh chỉnh chính sách.<br><strong>Vì sao các lựa chọn khác sai:</strong> Hồi tưởng thủ công không chính xác; bỏ qua quyền là bỏ kiểm soát; CLAUDE.md không chứa dữ liệu về lần hỏi quyền."},
  {"level": 3, "q": "Đội web chạy Playwright E2E qua Claude Code. Lệnh <code>pnpm --filter web e2e</code> cần mở trình duyệt và gọi staging API. Chính sách hợp lý nhất?", "options": ["ask cho lệnh e2e (gọi môi trường staging dùng chung), allow cho unit test cục bộ", "allow vì chỉ là test", "deny vì trình duyệt nguy hiểm", "Không cấu hình, dùng bypassPermissions"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> E2E gọi môi trường dùng chung nên có tác động ra ngoài; ask giữ con người trong vòng lặp, còn unit test cục bộ thì an toàn để allow.<br><strong>Vì sao các lựa chọn khác sai:</strong> Gọi là “test” không đồng nghĩa không có tác động; deny chặn quy trình hợp lệ; bypass bỏ mọi kiểm soát."},
  {"level": 3, "q": "Lập luận nào đúng khi so sánh “chỉ dùng rule” và “rule + hook” cho chính sách permission của monorepo?", "options": ["Hook luôn tốt hơn rule nên bỏ rule", "Rule đơn giản, dễ audit cho chặn tĩnh theo tên tool/đường dẫn; hook bổ sung cho logic động theo nội dung input, đổi lại phải bảo trì code và tốn thời gian chạy", "Rule luôn đủ, hook không bao giờ cần", "Hook chạy sau rule nên không chặn được gì"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Chọn công cụ theo loại kiểm tra: tĩnh → rule, động → hook; hai lớp bổ trợ nhau.<br><strong>Vì sao các lựa chọn khác sai:</strong> Bỏ rule mất lớp đơn giản dễ kiểm tra; rule không hiểu nội dung input; hook PreToolUse chạy trước kiểm tra quyền và chặn được."},
  {"level": 3, "q": "Một repo có <code>.claude/settings.json</code> cho phép <code>Bash(pnpm test:*)</code>. Kẻ xấu mở PR sửa script <code>test</code> trong package.json thành lệnh tải mã độc. Job CI review bằng Claude Code checkout PR và chạy test. Rủi ro và cách giảm?", "options": ["Không rủi ro vì rule chỉ cho pnpm test", "Chặn bằng cách đổi tên script thành test2", "Rule allow theo tên lệnh không bảo vệ khi nội dung script bị thay đổi; với PR không tin cậy nên chạy trong runner cô lập không secret, hoặc không chạy script của PR", "Chuyển rule sang settings.local.json là đủ"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Permission rule khớp theo chuỗi lệnh, còn pnpm test chạy bất cứ gì package.json định nghĩa; code không tin cậy phải được cô lập ở tầng hạ tầng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tên lệnh không nói gì về nội dung; đổi tên chỉ là che mắt; settings.local.json không tồn tại trên runner CI."},
  {"level": 3, "q": "Khác với danh sách permission (được gộp), một khoá giá trị đơn như <code>model</code> xuất hiện ở nhiều tầng thì lấy giá trị nào?<pre><code>// .claude/settings.json (team)\n{ \"model\": \"claude-sonnet-5\" }\n\n// .claude/settings.local.json (cá nhân)\n{ \"model\": \"claude-opus-5\" }</code></pre>Không có managed settings hay cờ --settings. Phiên dùng model nào?", "options": ["claude-sonnet-5, vì file team luôn thắng", "Cả hai được gộp và chọn ngẫu nhiên", "Lỗi cấu hình do trùng khoá", "claude-opus-5, vì local có ưu tiên cao hơn project đối với khoá giá trị đơn"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Với khoá đơn, tầng ưu tiên cao hơn ghi đè tầng thấp hơn theo thứ tự managed > --settings > local > project > user.<br><strong>Vì sao các lựa chọn khác sai:</strong> File team nằm dưới local; giá trị đơn không “gộp” được; trùng khoá giữa các tầng là thiết kế bình thường, không phải lỗi."}
];
